<?php
declare(strict_types=1);namespace App\Repositories;use PDO;
final readonly class RtmpRepository{public function __construct(private PDO $db){}public function servers():array{return $this->db->query("SELECT s.id,s.name,s.public_ip,s.private_ip,s.status,c.id config_id,c.enabled,c.port,c.application_name,c.desired_version,c.applied_version,c.status config_status,c.last_error,GROUP_CONCAT(i.ip ORDER BY i.ip SEPARATOR '\n') allowed_ips FROM servers s LEFT JOIN rtmp_ingest_configs c ON c.server_id=s.id LEFT JOIN rtmp_ingest_ips i ON i.config_id=c.id GROUP BY s.id ORDER BY s.name")->fetchAll();}public function find(int $id):?array{$s=$this->db->prepare('SELECT c.*,s.name,s.public_ip,s.private_ip FROM rtmp_ingest_configs c JOIN servers s ON s.id=c.server_id WHERE c.id=?');$s->execute([$id]);return $s->fetch()?:null;}}
